  <script>
    // reveal
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(prefersReduced){ items.forEach(i=>i.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.1});
      items.forEach(i=>io.observe(i));
    })();

